function frame(){requestAnimationFrame(frame);const realDt=Math.min(clock.getDelta(),.05);const dt=state.started&&!state.paused&&!state.ended?realDt*state.timeScale:0;if(dt)updateSimulation(dt);const t=clock.elapsedTime;updateScene(t,realDt);if(state.view==='chart')drawChart(t);else renderer.render(scene,camera);uiTime+=realDt;if(uiTime>.15){updateUI();uiTime=0}}
$('startBtn').onclick=start;$('pauseBtn').onclick=()=>setPause(!state.paused);$('audioBtn').onclick=toggleSound;$('fireBtn').onclick=fire;$('targetBtn').onclick=cycleTarget;$('portBtn').onclick=()=>{state.orderedHeading=(state.orderedHeading-15+360)%360};$('starboardBtn').onclick=()=>{state.orderedHeading=(state.orderedHeading+15)%360};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>setSpeed(+b.dataset.speed));document.querySelectorAll('[data-depth]').forEach(b=>b.onclick=()=>setDepth(+b.dataset.depth));document.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{state.timeScale=+b.dataset.time;document.querySelectorAll('[data-time]').forEach(e=>e.classList.toggle('active',e===b));notice('Time compression: '+state.timeScale+'×')});
function openHelp(){stalePause=state.paused;if(state.started)state.paused=true;$('helpDialog').showModal()}function closeHelp(){$('helpDialog').close();state.paused=stalePause} $('helpBtn').onclick=openHelp;$('controlsBtn').onclick=openHelp;$('closeHelp').onclick=closeHelp;$('readyBtn').onclick=closeHelp;$('helpDialog').addEventListener('cancel',()=>{state.paused=stalePause});$('restartBtn').onclick=()=>location.reload();
window.addEventListener('keydown',e=>{if($('helpDialog').open||$('endDialog').open)return;const k=e.key.toLowerCase();if([' ','tab','arrowup','arrowdown'].includes(k))e.preventDefault();if(e.repeat){if(k==='a'||k==='d')keys.add(k);return}keys.add(k);if(k==='1')setView('bridge');if(k==='2')setView('scope');if(k==='3')setView('chart');if(k==='p')setPause(!state.paused);if(k==='h')openHelp();if(k==='c')setDepth(80);if(k==='r')setDepth(12);if(k==='tab')cycleTarget();if(k===' ')fire();if(k==='w'||k==='s'){const speeds=[0,2,4,8,14],ix=speeds.indexOf(state.orderedSpeed);setSpeed(speeds[clamp(ix+(k==='w'?1:-1),0,4)])}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();if(state.started&&!state.paused&&!state.ended)setPause(true)});$('world').addEventListener('pointerdown',e=>{dragging=true;lastX=e.clientX;lastY=e.clientY;$('world').setPointerCapture(e.pointerId)});$('world').addEventListener('pointermove',e=>{if(!dragging)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;if(state.view==='scope')scopeBearing=(scopeBearing+dx*.09+360)%360;else{orbitYaw-=dx*.005;orbitPitch=clamp(orbitPitch+dy*.004,.06,1.25)}});$('world').addEventListener('pointerup',()=>dragging=false);$('world').addEventListener('pointercancel',()=>dragging=false);$('world').addEventListener('wheel',e=>{e.preventDefault();if(state.view==='scope')scopeFov=clamp(scopeFov+e.deltaY*.025,8,48);else orbitDistance=clamp(orbitDistance+e.deltaY*.15,65,450)},{passive:false});
